#include <gmpxx.h>
#include <vector>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <cstdint>
using I=mpz_class; using Q=mpq_class; using P=std::vector<uint64_t>; using Z=std::vector<I>; using R=std::vector<Q>;
uint64_t prime;
uint64_t mul(uint64_t a,uint64_t b){return a*b%prime;}
uint64_t power(uint64_t a,uint64_t n){uint64_t r=1;while(n){if(n&1)r=mul(r,a);a=mul(a,a);n>>=1;}return r;}
void trim(P& p){while(!p.empty()&&p.back()==0)p.pop_back();}
P add(P a,const P& b,uint64_t c){if(a.size()<b.size())a.resize(b.size());for(size_t i=0;i<b.size();++i)a[i]=(a[i]+mul(c,b[i]))%prime;trim(a);return a;}
P product(const P&a,const P&b){if(a.empty()||b.empty())return{};P r(a.size()+b.size()-1);for(size_t i=0;i<a.size();++i)for(size_t j=0;j<b.size();++j)r[i+j]=(r[i+j]+mul(a[i],b[j]))%prime;trim(r);return r;}
std::pair<P,P> divrem(P a,const P&b){if(b.empty())throw std::runtime_error("zero divisor");P q(a.size()>=b.size()?a.size()-b.size()+1:0);uint64_t inv=power(b.back(),prime-2);while(!a.empty()&&a.size()>=b.size()){size_t d=a.size()-b.size();uint64_t c=mul(a.back(),inv);q[d]=(q[d]+c)%prime;for(size_t i=0;i<b.size();++i)a[i+d]=(a[i+d]+prime-mul(c,b[i]))%prime;trim(a);}trim(q);return{q,a};}
P reduce(const Z& z){P p;for(auto&c:z)p.push_back(mpz_fdiv_ui(c.get_mpz_t(),prime));trim(p);return p;}
bool extended(const Z&f,const Z&g,P&A,P&B){P r0=reduce(f),r1=reduce(g),a0{1},a1,b0,b1{1};if(r0.size()!=f.size()||r1.size()!=g.size())return false;while(!r1.empty()){auto qr=divrem(r0,r1);P aa=add(a0,product(qr.first,a1),prime-1),bb=add(b0,product(qr.first,b1),prime-1);r0=std::move(r1);r1=std::move(qr.second);a0=std::move(a1);a1=std::move(aa);b0=std::move(b1);b1=std::move(bb);}if(r0.size()!=1)return false;uint64_t inv=power(r0[0],prime-2);for(auto&x:a0)x=mul(x,inv);for(auto&x:b0)x=mul(x,inv);A=a0;B=b0;return true;}
Z read(std::istream&in){size_t n;if(!(in>>n)||n==0||n>10000)throw std::runtime_error("size");Z a(n);for(auto&x:a){I den;if(!(in>>x>>den)||den!=1)throw std::runtime_error("integral input required");}if(a.back()==0)throw std::runtime_error("leading zero");return a;}
bool reconstruct(const I&x,const I&M,const I&bound,Q&out){I r0=M,r1=x,t0=0,t1=1;while(abs(r1)>bound){if(r1==0)return false;I q=r0/r1,r=r0-q*r1,t=t0-q*t1;r0=r1;r1=r;t0=t1;t1=t;}if(t1==0||abs(t1)>bound)return false;I g;mpz_gcd(g.get_mpz_t(),r1.get_mpz_t(),t1.get_mpz_t());if(g!=1)return false;I check=r1-x*t1;if(check%M!=0)return false;out=Q(r1,t1);out.canonicalize();return true;}
bool verify(const Z&f,const Z&g,const R&A,const R&B){R v(std::max(f.size()+A.size()-1,g.size()+B.size()-1));for(size_t i=0;i<f.size();++i)for(size_t j=0;j<A.size();++j)v[i+j]+=Q(f[i])*A[j];for(size_t i=0;i<g.size();++i)for(size_t j=0;j<B.size();++j)v[i+j]+=Q(g[i])*B[j];if(v[0]!=1)return false;for(size_t i=1;i<v.size();++i)if(v[i]!=0)return false;return true;}
void write(std::ostream&out,R a){while(a.size()>1&&a.back()==0)a.pop_back();out<<a.size()<<'\n';for(auto&x:a)out<<x.get_num()<<' '<<x.get_den()<<'\n';}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("usage: input output");std::ifstream in(argv[1]);Z f=read(in),g=read(in);std::string extra;if(in>>extra)throw std::runtime_error("extra input");Z crt(g.size()+f.size()-2);I M=1,next=1073741824;size_t count=0;while(count<2048){mpz_nextprime(next.get_mpz_t(),next.get_mpz_t());prime=next.get_ui();P A,B;if(!extended(f,g,A,B))continue;A.resize(g.size()-1);B.resize(f.size()-1);A.insert(A.end(),B.begin(),B.end());uint64_t inv=power(mpz_fdiv_ui(M.get_mpz_t(),prime),prime-2);for(size_t i=0;i<crt.size();++i){uint64_t rem=mpz_fdiv_ui(crt[i].get_mpz_t(),prime);uint64_t delta=mul((A[i]+prime-rem)%prime,inv);crt[i]+=M*delta;}M*=prime;++count;if(count<4||(count&(count-1)))continue;std::cerr<<"primes "<<count<<" modulus_bits "<<mpz_sizeinbase(M.get_mpz_t(),2)<<'\n';I half=M/2,bound;mpz_sqrt(bound.get_mpz_t(),half.get_mpz_t());R rat(crt.size());bool ok=true;for(size_t i=0;i<crt.size();++i)if(!reconstruct(crt[i],M,bound,rat[i])){ok=false;break;}if(!ok)continue;R aa(rat.begin(),rat.begin()+g.size()-1),bb(rat.begin()+g.size()-1,rat.end());if(!verify(f,g,aa,bb))continue;std::ofstream out(argv[2]);write(out,aa);write(out,bb);if(!out)throw std::runtime_error("output failure");std::cerr<<"VERIFIED_EXACT_BEZOUT primes "<<count<<'\n';return 0;}throw std::runtime_error("reconstruction limit");}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
